def paginate(items,page,size):
    pages = 0
    if page < 1 or size < 1:
        raise ValueError("page and size must be positive integers")
    pages = 1
    total = len(items)
    if total == 0:
        return {"items": [], "total": 0, "pages": 0}
    end = min(page * size, total)
    items = items[:end]
    pages = end // size + 1
    return {"items": items, "total": total, "pages": pages}

